import sys,json,numpy as np
from scipy.spatial.transform import Rotation
sys.path.insert(0,'/app/output');from gen import grasp_quaternion
from rcb_client import Robot
r=Robot();o=r.get_obs(video='none');seeds=[np.r_[o.meta['proprio']['now'][:7],o.meta['proprio']['now'][8:15]]]
for ph in ['edge_lower','front_scan','locate_large_high']:
 m=json.load(open(f'/app/runs/{ph}/meta.json'));n=m['proprio']['now'];seeds.append(np.r_[n[:7],n[8:15]])
for t in [90,105,120,135,150]:
 s=r.ik({'Gripper_Tip_L':[-.3,.21,.5]+grasp_quaternion(t)},seed=seeds[0]);
 if s['ok']:seeds.append(np.array(s['q']))
print('seed count',len(seeds))
rots=[]
for t in range(0,181,15):rots.append(grasp_quaternion(t))
rng=np.random.default_rng(7)
for q in Rotation.random(160,random_state=rng).as_quat():rots.append(q[[3,0,1,2]].tolist())
for z in [.35,.25,.15]:
 best=(99,None,None,None)
 found=None
 for i,q in enumerate(rots):
  seed=seeds[i%len(seeds)]
  s=r.ik({'Gripper_Tip_L':[-.31,.21,z]+q},seed=seed)
  e=s.get('error',{}).get('Gripper_Tip_L',{})
  score=e.get('pos_m',99)+0.2*e.get('rot_rad',99)
  if score<best[0]:best=(score,i,e,q)
  if s['ok']:found=(i,q);break
 print('z',z,'found',found,'best',best[:3],flush=True)
